use converter_core::*;use std::fs;#[test]fn csv_json(){let d=std::env::temp_dir();let i=d.join("a.csv");let o=d.join("a.json");fs::write(&i,"name,age\nAda,37").unwrap();let r=convert_file(&ConversionRequest{input:i.to_string_lossy().into(),output:o.to_string_lossy().into(),target:FileFormat::Json}).unwrap();assert!(r.bytes_written>0);assert!(fs::read_to_string(o).unwrap().contains("Ada"));}
#[test]fn markdown_txt(){let d=std::env::temp_dir();let i=d.join("a.md");let o=d.join("a.txt");fs::write(&i,"# Title\n**bold**").unwrap();convert_file(&ConversionRequest{input:i.to_string_lossy().into(),output:o.to_string_lossy().into(),target:FileFormat::Txt}).unwrap();assert_eq!(fs::read_to_string(o).unwrap(),"Title\nbold");}
